function Button({ variant = 'primary', children, ...props }) {
  const base = 'inline-flex items-center px-4 py-2 rounded-md font-medium text-sm transition-colors';
  const variants = {
    primary: 'bg-blue-600 hover:bg-blue-700 text-white',
    secondary: 'bg-white border border-gray-300 hover:bg-gray-50',
    ghost: 'bg-transparent hover:bg-gray-100 text-gray-700',
  };
  return <button className={`${base} ${variants[variant]}`} {...props}>{children}</button>;
}
